import { Component, Renderer2, OnInit, OnDestroy } from '@angular/core';

@Component({
  selector: 'app-cotacao',
  templateUrl: './cotacao.component.html',
  styleUrls: ['./cotacao.component.css']
})
export class CotacaoComponent implements OnInit, OnDestroy {
  cotacao = {
    nome: '',
    email: '',
    tipo: ''
  };

  constructor(private renderer: Renderer2) { }

  ngOnInit() {
    this.renderer.addClass(document.body, 'blurred-bg');
  }

  ngOnDestroy() {
    this.renderer.removeClass(document.body, 'blurred-bg');
  }

  enviarCotacao() {
    alert('Cotação enviada com sucesso!');
    window.history.back();
  }

  fecharCotacao() {
    window.history.back();
  }
}
<div class="popup-cotacao-backdrop" (click)="fecharCotacao()" (keydown.escape)="fecharCotacao()">
  <div class="popup-cotacao-content shadow rounded p-4 bg-white" style="max-width:400px;margin:40px auto;" (click)="$event.stopPropagation()" (keydown.escape)="fecharCotacao()">
    <button class="btn-close float-end" aria-label="Fechar" (click)="fecharCotacao()"></button>
    <h2 class="h4 mb-3 text-primary">Cotação de Seguro</h2>
    <form (ngSubmit)="enviarCotacao()" #cotacaoForm="ngForm">
      <div class="mb-3">
        <label class="form-label" for="cotacao-nome">Nome</label>
        <input id="cotacao-nome" class="form-control" name="nome" [(ngModel)]="cotacao.nome" required />
      </div>
      <div class="mb-3">
        <label class="form-label" for="cotacao-email">Email</label>
        <input id="cotacao-email" class="form-control" name="email" [(ngModel)]="cotacao.email" required type="email" />
      </div>
      <div class="mb-3">
        <label class="form-label" for="cotacao-tipo">Tipo de Seguro</label>
        <select id="cotacao-tipo" class="form-select" name="tipo" [(ngModel)]="cotacao.tipo" required>
          <option value="" disabled selected>Selecione</option>
          <option value="auto">Auto</option>
          <option value="residencial">Residencial</option>
          <option value="vida">Vida</option>
        </select>
      </div>
      <div class="d-flex justify-content-between">
        <button class="btn btn-primary" type="submit" [disabled]="!cotacaoForm.form.valid">Enviar</button>
        <button class="btn btn-outline-secondary" type="button" (click)="fecharCotacao()">Cancelar</button>
      </div>
    </form>
  </div>
</div>
